        match self {
            Ecosystem::Cargo => 0,
            Ecosystem::Npm => 1,
            Ecosystem::Pypi => 2,
            _ => u8::MAX,
        }
    }

    /// The three ecosystems package *identity discovery* treats as
    /// canonical -- each has exactly one manifest format
